package com.mealmate.delivery; import org.springframework.kafka.annotation.*; import org.springframework.kafka.core.*; import org.springframework.stereotype.*; import java.util.*; @Component class DeliveryConsumer{final DeliveryRepository r;final KafkaTemplate<String,Object> k;DeliveryConsumer(DeliveryRepository x,KafkaTemplate<String,Object> y){r=x;k=y;}@KafkaListener(topics="payment-events",groupId="delivery-service")void on(Event e){if(!"PaymentSucceeded".equals(e.type())||r.existsById(e.orderId()))return;boolean f=e.failDeliveryAssignment();r.save(new Delivery(e.orderId(),f?"FAILED":"ASSIGNED"));k.send("delivery-events",e.orderId().toString(),new Event(UUID.randomUUID().toString(),f?"DeliveryAssignmentFailed":"DeliveryAssigned",e.orderId(),false,f));}record Event(String eventId,String type,UUID orderId,boolean failPayment,boolean failDeliveryAssignment){}}
